import { DocumentsOfTypeResult, StudioProApi } from "@mendix/extensions-api";
import { ModelDocument } from "../types/modelDocument";

export const getCustomBlobDocumentByQualifiedName = async (
    studioPro: StudioProApi,
    qualifiedName: string,
    documentTypeId: string
): Promise<DocumentsOfTypeResult[0] | undefined> => {
    //TODO fix typing, used to be DocumentsOfTypeResult, see SAS-1808
    const documents = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(documentTypeId);
    // @ts-ignore
    return documents.matchingDocumentsInfo.find((d) => d.moduleName + "." + d.name === qualifiedName);
};

export const handleShowCustomBlobDocument = async (
    studioPro: StudioProApi,
    modelDocument: ModelDocument,
    documentTypeId: string
): Promise<void> => {
    const document = await getCustomBlobDocumentByQualifiedName(studioPro, modelDocument.qualifiedName, documentTypeId);

    if (!document) {
        const errorMessage = "Could not find document.";
        const errorDetails = "This document might have been deleted or renamed. Please update the selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }
    await studioPro.ui.editors.editDocument(modelDocument.documentId);
};
